INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(91950, 0, 0, 'Alright, fine, but he owes me, make sure you tell him!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66650'),
(91854, 0, 0, 'I have not spoken with Haz\'gorg in some time, but my people are also going through much the same as he, the Gor\'dosh have fallen on dark times, and are ruled by a tyrant. I hold no power any longer, but if I can help the Maul\'ogg then perhaps I have done something for the greater good.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66685'),
(91854, 1, 0, 'Before the Tyrant King came into power, I had dabbled with the idea of making an elixir, a potion, or a spell to sway his mind into seeking less hostile means, perhaps this could work with Lord Cruk\'Zogg, to pacify him from being engulfed into madness, bring this information back to Haz\'gorg, perhaps he can figure out something that I could not.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66686'),
(92002, 0, 0, 'It is done, the tyranny of Lapidis has come to an end! Admiral Caelan\'s soul is put to rest, cheers to $N for their heroic actions!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 67028'),
(60467, 0, 0, 'Who let you in this tower?! Do you know who you are messing with?!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66414'),
(60467, 1, 0, 'You know.. Nothing... I was more powerful then all of you.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66415'),
(92142, 0, 0, 'You wont stand a chance against me scurvy dog!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66402'),
(92936, 0, 0, 'I knew Arnold was still out there somewhere, though I cannot imagine what it would be like stranded on some island at sea. Hopefully he returns home safely.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66643'),
(92936, 1, 0, 'I have a letter for you, deliver it to him and with haste.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66644'),
(1242, 100, 0, 'A letter from Arnold... I thought he died at sea, I haven\'t heard from him in such a long time.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66645'),
(1242, 101, 0, 'This is splendid news, here, please, take this to him.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66646'),
(2543, 100, 0, 'That certainly was challenging, but I have finished my work, the key should be enchanted.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66991'),
(2543, 101, 0, 'Halister? I haven\'t heard from him in ages. We need to meet, as there is much to discuss. As for the Arcane Resonator, I can lend you one. But tell Halister that he needs to bring it back to me in person!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66187');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9091950, 'Cooking is a fine art, and working with such few resources at our disposal makes it an even finer art.', 'Cooking is a fine art, and working with such few resources at our disposal makes it an even finer art.', 1, 0);
